<div class="admin-page-head"><h1>ویرایش لینک منو</h1><?= CHtml::link('بازگشت',array('adminMenu/index'),array('class'=>'btn btn-outline')) ?></div>
<section class="panel narrow-panel"><?php $form=$this->beginWidget('CActiveForm'); ?><?= $form->errorSummary($model) ?>
<?php foreach(array('label'=>'عنوان لینک','url'=>'مسیر داخلی یا آدرس HTTPS') as $key=>$label): ?><div class="field"><label><?= $label ?></label><?= $form->textField($model,$key,array('required'=>true)) ?></div><?php endforeach; ?>
<div class="field"><label>محل نمایش</label><?= $form->dropDownList($model,'location',array('header'=>'بالای سایت','footer'=>'پایین سایت')) ?></div><div class="field"><label>والد</label><?= $form->dropDownList($model,'parent_id',$parents,array('prompt'=>'بدون والد')) ?></div><div class="field"><label>ترتیب نمایش</label><?= $form->numberField($model,'sort_order',array('min'=>0)) ?></div><div class="check-field"><?= $form->checkBox($model,'is_active') ?><label>فعال</label></div><?= CHtml::submitButton('ذخیره لینک',array('class'=>'btn btn-primary')) ?><?php $this->endWidget(); ?></section>
<?php if(!$model->isNewRecord): ?><?= CHtml::beginForm(array('adminMenu/delete','id'=>$model->id),'post',array('data-confirm'=>'لینک حذف شود؟ زیرمنوها به والد بالاتر منتقل می‌شوند.')) ?><?= CHtml::submitButton('حذف لینک',array('class'=>'btn btn-danger')) ?><?= CHtml::endForm() ?><?php endif; ?>
